import data from "./generic-foods.json";
import type { FoodCandidate } from "./portion";

/**
 * Generic (unbranded) foods from USDA FoodData Central SR Legacy — public
 * domain. Values are generated by scripts/build-generic-foods.mjs from the
 * official dataset; nothing here is typed by hand.
 */
export interface GenericFood {
  id: number;
  name: string;
  /** Original USDA description, for traceability. */
  en: string;
  per100g: { calories: number; protein: number; carbs: number; fat: number };
  fiber?: number;
  sugars?: number;
  sodiumMg?: number;
  serving?: { label: string; grams: number };
}

export const GENERIC_FOODS = data as GenericFood[];

export const normalizeText = (s: string) =>
  s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().trim();

export function genericCandidate(g: GenericFood): FoodCandidate {
  return {
    name: g.name,
    per100g: g.per100g,
    servingGrams: g.serving?.grams,
    servingName: g.serving?.label,
    fdcId: g.id,
    source: "generic",
  };
}

/**
 * Accent-insensitive search. Every word of the query must start a word of the
 * name ("pollo asado" → "Pechuga de pollo asada"); results that start with the
 * query come first.
 */
export function searchGeneric(query: string, foods: readonly GenericFood[] = GENERIC_FOODS, limit = 20): GenericFood[] {
  const terms = normalizeText(query).split(/\s+/).filter((t) => t.length > 0);
  if (terms.length === 0) return [];
  const scored: { g: GenericFood; score: number }[] = [];
  for (const g of foods) {
    const name = normalizeText(g.name);
    const words = name.split(/[^a-z0-9ñ]+/).filter(Boolean);
    if (!terms.every((t) => words.some((w) => w.startsWith(t)))) continue;
    const score = (name.startsWith(terms[0]) ? 0 : 1) * 1000 + name.length;
    scored.push({ g, score });
  }
  return scored.sort((a, b) => a.score - b.score).slice(0, limit).map((s) => s.g);
}
